SELECT DATE(data_time) as xdata, COALESCE(SUM(CASE WHEN type = '尖' THEN value ELSE 0 END), 0) as ytip, COALESCE(SUM(CASE WHEN type = '峰' THEN value ELSE 0 END), 0) as ypeak, COALESCE(SUM(CASE WHEN type = '平' THEN value ELSE 0 END), 0) as yflat, COALESCE(SUM(CASE WHEN type = '谷' THEN value ELSE 0 END), 0) as ytrough, COALESCE(SUM(CASE WHEN type = '深谷' THEN value ELSE 0 END), 0) as ydeep FROM electricity_data_item
AND device_id = #{deviceId}
AND data_time >= #{startTime}
AND data_time <= #{endTime}
GROUP BY DATE(data_time) ORDER BY DATE(data_time)

SELECT DATE(data_time) as dataTime, type, COALESCE(SUM(value), 0) as totalValue, COALESCE(SUM(cost), 0) as totalCost, AVG(price) as avgPrice FROM electricity_data_item
AND device_id = #{deviceId}
AND data_time >= #{startTime}
AND data_time <= #{endTime}
GROUP BY DATE(data_time), type ORDER BY DATE(data_time), type
